// Cable bridge - lets cables cross under a bench mat
// Print orientation: flat on the bed, tunnel opening downward

$fn = 96;

// --- Block dimensions ---
block_len   = 60;   // length along X (mm)
block_wid   = 50;   // width along Y (mm)
block_ht    = 15;   // height along Z (mm)

// --- Tunnel dimensions ---
tunnel_d    = 10;   // tunnel diameter (mm); semicircle at floor level
tunnel_x    = 0;    // tunnel axis X position (mm)

// --- Cutting overlap ---
eps         = 0.5;  // extension of cutters past faces (mm)

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnel: full cylinder with axis along Y at z = 0;
    // only the upper half lies inside the block
    translate([tunnel_x, 0, 0])
        rotate([90, 0, 0])
            cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
}

// Cable bridge - lets cables cross under a bench mat
// Print orientation: flat on the bed, tunnel opening at floor level

$fn = 96;

// ---- Dimensions (mm) ----
block_len    = 80;   // length along X
block_wid    = 30;   // width along Y (tunnel runs along this axis)
block_h      = 15;   // height along Z
tunnel_d     = 12;   // tunnel cylinder diameter (axis at x=0, z=0)
tunnel_r     = tunnel_d / 2;
cut_extra    = 1;    // overshoot of cutters past faces

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_h]);

    // Semicircular tunnel: cylinder along Y, axis at x = 0, z = 0
    // (lower half lies below the bed, so only the upper half is removed)
    rotate([-90, 0, 0])
        translate([0, 0, -block_wid/2 - cut_extra])
            cylinder(r = tunnel_r, h = block_wid + 2*cut_extra);
}

// Cable bridge - lets cables cross under a bench mat
// Print orientation: flat on the bed, tunnels open at the bottom

// ---- Block dimensions ----
block_len   = 100;   // length along X (mm)
block_wid   = 40;    // width along Y (mm)
block_ht    = 15;    // height along Z (mm)

// ---- Tunnel dimensions ----
tunnel_d     = 8;    // tunnel cylinder diameter (mm)
tunnel_count = 2;    // number of tunnels
tunnel_pitch = 16;   // centre-to-centre spacing of tunnel axes along X (mm)

// ---- Misc ----
eps = 0.5;           // overcut past faces in difference()
$fn = 96;            // curve resolution

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinders with axis along Y at z = 0.
    // The lower half sits below the bed, so only the upper half cuts the block.
    for (i = [0 : tunnel_count - 1]) {
        x = (i - (tunnel_count - 1) / 2) * tunnel_pitch;
        translate([x, 0, 0])
            rotate([90, 0, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
}

