    // Main block, centred in X and Y, resting on z = 0
    translate([-block_length / 2, -block_width / 2, 0])
        cube([block_length, block_width, block_height]);

    // Semicircular tunnels: cylinders with axis along Y at z = 0
    // (lower half lies below the bed, leaving a half-round channel)
    for (i = [0 : tunnel_count - 1])
        translate([first_x + i * tunnel_pitch, 0, 0])
            rotate([90, 0, 0])
                cylinder(r = tunnel_r,
                         h = block_width + 2 * cut_overrun,
                         center = true);
}

