// ---- Dimensions (mm) ----
tube_d      = 16;              // diameter of the round cross-section
tube_r      = tube_d / 2;      // radius of the cross-section (8 mm)
sweep_r     = 20;              // radius of the circle the section centre follows
outer_d     = 2 * (sweep_r + tube_r); // overall diameter (56 mm)
inner_d     = 2 * (sweep_r - tube_r); // hole diameter (24 mm)
mid_z       = tube_r;          // middle plane height (8 mm), ring rests on z = 0

// ---- Resolution ----
$fn = 128;                     // smoothness of curved surfaces

// ---- Model ----
translate([0, 0, mid_z])
    rotate_extrude($fn = 128)
        translate([sweep_r, 0, 0])
            circle(r = tube_r, $fn = 64);

